3	/**
4	 * Derives an owner's segment, formatted {@code <TIER>_<AREA>} — one of {@code PREMIUM_METRO},
5	 * {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}.
6	 *
7	 * <p>TIER is {@code PREMIUM} when {@code membershipLevel} is 3 or more, otherwise {@code STANDARD}.
8	 * AREA is {@code METRO} when the locality is a known region (NSW, VIC or QLD), otherwise
9	 * {@code REGIONAL}.
10	 */
11	public final class OwnerSegment {
12	
13	    private OwnerSegment() {
14	    }
15	
16	    /** The {@code <TIER>_<AREA>} segment for the given membership level and locality/region. */
17	    public static String of(Integer membershipLevel, String locality) {
18	        String tier = membershipLevel != null && membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
19	        String area = isKnownRegion(locality) ? "METRO" : "REGIONAL";
20	        return tier + "_" + area;
21	    }
22	
23	    private static boolean isKnownRegion(String locality) {
24	        return "NSW".equals(locality) || "VIC".equals(locality) || "QLD".equals(locality);
25	    }
26	}
